def fk(q):
 p=P.copy();ax=A.copy();R=np.eye(3)
 for i,a in enumerate(q):
  u=ax[i]/np.linalg.norm(ax[i]);c=np.cos(a);sn=np.sin(a);W=c*np.eye(3)+(1-c)*np.outer(u,u)+sn*np.array([[0,-u[2],u[1]],[u[2],0,-u[0]],[-u[1],u[0],0]]);p[i+1:]=(p[i+1:]-p[i])@W.T+p[i];ax[i+1:]=ax[i+1:]@W.T;R=W@R
 return p[-1],R
print('q',q)
for target,jaw in [(np.array([.514,-.051,.015]),np.array([1.,0,0])),(np.array([.3,0,.8]),np.array([1.,0,0])),(np.array([.657,0,.72]),np.array([1.,0,0]))]:
 for reg in [.006,.02,.05,.1]:
  lo=np.array([-10,-2.24,-10,-2.57,-10,-2.09,-10]);hi=-lo;lo[[0,2,4,6]]=q[[0,2,4,6]]-2*np.pi;hi[[0,2,4,6]]=q[[0,2,4,6]]+2*np.pi
  def f(v):
   p,R=fk(v);return np.r_[p-target,.18*(R[:,2]-[0,0,-1]),.18*(R@[-1,0,0]-jaw),reg*(v-q)]
  so=least_squares(f,q,bounds=(lo,hi),max_nfev=400);print('t',target,'reg',reg,'normdq',round(np.linalg.norm(so.x-q),2),'max',round(np.max(np.abs(so.x-q)),2),'pred',np.round(fk(so.x)[0],2),'dq',np.round(so.x-q,1))
